CALL lake.system.expire_snapshots(
  table       => 'sales.orders',
  older_than  => TIMESTAMP '2026-11-10 00:00:00',
  retain_last => 50);

CALL lake.system.rewrite_manifests('sales.orders');

CALL lake.system.remove_orphan_files(
  table      => 'sales.orders',
  older_than => TIMESTAMP '2026-11-14 00:00:00',
  dry_run    => true);

ALTER TABLE lake.sales.orders WRITE ORDERED BY customer_id, order_ts;
-- or: keep partition-level distribution, sort only within each task
ALTER TABLE lake.sales.orders WRITE DISTRIBUTED BY PARTITION LOCALLY ORDERED BY customer_id;
